local Gilder = {}
local PRODUCTS = {
    gilded_page = { name = "Pozlačena stran", goldCost = 1, parchmentCost = 1, time = 3, cost = 50, prestige = 3, description = "Stran z zlatim lističem." },
    gilded_letter = { name = "Pozlačena začetnica", goldCost = 1, parchmentCost = 1, time = 5, cost = 80, prestige = 5, description = "Zlati listič na začetnici." },
    gilded_frame = { name = "Pozlačen okvir", goldCost = 2, woodCost = 2, time = 7, cost = 150, prestige = 8, description = "Okvir s pozlato." },
    gilded_statue = { name = "Pozlačen kip", goldCost = 3, bronzeCost = 2, time = 14, cost = 400, prestige = 20, description = "Bronasti kip s pozlato." },
    gilded_altar = { name = "Pozlačen oltar", goldCost = 5, woodCost = 5, stoneCost = 3, time = 30, cost = 1000, prestige = 30, faith = 20, description = "Oltar z zlatimi lističi." },
    gilded_crown = { name = "Pozlačena krona", goldCost = 4, jewelCost = 2, time = 20, cost = 800, prestige = 40, happiness = 10, description = "Krona z zlatom in drago kamen." },
}
local BUILDINGS = {
    workshop = { name = "Pozlatorska delavnica", cost = { gold = 300, wood = 100 }, upkeep = 10, qualityBonus = 5 },
    gilding_studio = { name = "Pozlatarski atelje", cost = { gold = 1500, wood = 200, stone = 300, gold = 50 }, upkeep = 35, qualityBonus = 20 },
    gold_beating_mill = { name = "Zlatarski mlin", cost = { gold = 2000, wood = 300, stone = 400, iron = 100 }, upkeep = 40, qualityBonus = 25, goldLeafProduction = 3 },
    royal_gilding = { name = "Kraljevski pozlatar", cost = { gold = 5000, wood = 400, stone = 800, gold = 100 }, upkeep = 100, qualityBonus = 40, prestigeBonus = 20 },
}
Gilder.goldStock = 8; Gilder.parchmentStock = 8; Gilder.woodStock = 8; Gilder.bronzeStock = 5; Gilder.stoneStock = 5; Gilder.jewelStock = 3
Gilder.productStock = {}; Gilder.buildings = {}; Gilder.gilder = nil; Gilder.activeMaking = {}; Gilder.totalProducts = 0; Gilder.dayTimer = 0
function Gilder.init() Gilder.goldStock=8; Gilder.parchmentStock=8; Gilder.woodStock=8; Gilder.bronzeStock=5; Gilder.stoneStock=5; Gilder.jewelStock=3; Gilder.productStock={}; Gilder.buildings={}; Gilder.gilder=nil; Gilder.activeMaking={}; Gilder.totalProducts=0; Gilder.dayTimer=0; print("[Gilder] Royal Book Illuminator & Gilder System initialized (6 products, 4 buildings)") end
function Gilder.hireGilder(n,s) s=s or math.random(40,85); local c=400+s*8; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Gilder.gilder={name=n or ("Pozlatar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pozlatar najet: %s (spretnost: %d)",Gilder.gilder.name,s),"success") end; return true end
function Gilder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Gilder.build(id) local ok,e=Gilder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Gilder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Gilder.getQualityBonus() local b=0; for _,bd in ipairs(Gilder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Gilder.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.goldCost and Gilder.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.parchmentCost and Gilder.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.woodCost and Gilder.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.bronzeCost and Gilder.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.stoneCost and Gilder.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.jewelCost and Gilder.jewelStock<(d.jewelCost or 0) then return false,"Premalo dragih kamnov" end; if #Gilder.buildings==0 then return false,"Potrebna delavnica" end; if not Gilder.gilder then return false,"Potreben pozlatar" end; return true end
function Gilder.make(pt) local ok,e=Gilder.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.goldCost then Gilder.goldStock=Gilder.goldStock-d.goldCost end; if d.parchmentCost then Gilder.parchmentStock=Gilder.parchmentStock-d.parchmentCost end; if d.woodCost then Gilder.woodStock=Gilder.woodStock-d.woodCost end; if d.bronzeCost then Gilder.bronzeStock=Gilder.bronzeStock-d.bronzeCost end; if d.stoneCost then Gilder.stoneStock=Gilder.stoneStock-d.stoneCost end; if d.jewelCost then Gilder.jewelStock=Gilder.jewelStock-d.jewelCost end; local t=d.time; if Gilder.gilder then t=math.max(1,t-math.floor(Gilder.gilder.skill/10)) end; table.insert(Gilder.activeMaking,{id="gild_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,prestige=d.prestige or 0,faith=d.faith or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pozlačevanje: %s (%d dni)",d.name,t),"info") end; return true end
function Gilder.completeMaking(m) local q=1.0+(Gilder.getQualityBonus()/100); if Gilder.gilder then q=q+(Gilder.gilder.skill/200) end; q=math.min(2.5,q); Gilder.productStock[m.productType]=(Gilder.productStock[m.productType] or 0)+1; Gilder.totalProducts=Gilder.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.faith>0 and _G.Religion then pcall(_G.Religion.addFaith,m.faith) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Gilder.gilder then Gilder.gilder.itemsMade=Gilder.gilder.itemsMade+1; if math.random()<0.15 then Gilder.gilder.skill=math.min(100,Gilder.gilder.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pozlata dokončana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Gilder.update(dt) if not _G.state then return end; Gilder.dayTimer=Gilder.dayTimer+dt; if Gilder.dayTimer>=30 then Gilder.dayTimer=0; for i=#Gilder.activeMaking,1,-1 do local m=Gilder.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Gilder.completeMaking(m); table.remove(Gilder.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Gilder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Gilder.gilder then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Gilder.getStats() return {goldStock=Gilder.goldStock,parchmentStock=Gilder.parchmentStock,woodStock=Gilder.woodStock,bronzeStock=Gilder.bronzeStock,productStock=Gilder.productStock,numBuildings=#Gilder.buildings,hasGilder=Gilder.gilder~=nil,gilderName=Gilder.gilder and Gilder.gilder.name or "—",gilderSkill=Gilder.gilder and Gilder.gilder.skill or 0,activeMaking=#Gilder.activeMaking,totalProducts=Gilder.totalProducts} end
return Gilder
